class UnsavedChangesConfirmWidget extends StatefulWidget {
  const UnsavedChangesConfirmWidget({
    super.key,
    required this.child,
    required this.hasUnsavedChanges,
    required this.onSave,
    required this.onDiscard,
  });

  final Widget child;
  final bool hasUnsavedChanges;
  final VoidCallback onSave;
  final VoidCallback onDiscard;

  @override
  State<UnsavedChangesConfirmWidget> createState() =>
      _UnsavedChangesConfirmWidgetState();
}

class _UnsavedChangesConfirmWidgetState
    extends State<UnsavedChangesConfirmWidget> {
  late final WillPopScope _willPopScope;

  @override
  Widget build(BuildContext context) {
    _willPopScope = WillPopScope(
      onWillPop: _onWillPop,
      child: widget.child,
    );
    return _willPopScope;
  }

  Future<bool> _onWillPop() async {
    if (!widget.hasUnsavedChanges) {
      return true;
    }

    final result = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Unsaved Changes'),
        content: const Text(
          'You have unsaved changes. Do you want to save them before leaving?',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('Cancel'),
          ),
          TextButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: const Text('Discard'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(context).pop('save'),
            child: const Text('Save'),
          ),
        ],
      ),
    );

    if (result == 'save') {
      widget.onSave();
      return false;
    } else if (result == true) {
      widget.onDiscard();
      return true;
    }

    return false;
  }
}
